import { useState, useEffect } from "react";
import { Search, Lock, Unlock, UserPlus, RotateCcw } from "lucide-react";
import { useAuth } from "../../context/AuthContext";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import type { Patient } from "../../types/models";
import { API_BASE_URL } from "../../config";

export default function PatientList() {
    const { token } = useAuth();
    const navigate = useNavigate();
    const [search, setSearch] = useState("");
    const [patients, setPatients] = useState<Patient[]>([]);
    const [loading, setLoading] = useState(false);

    const searchPatients = async (query: string = "") => {
        setLoading(true);
        try {
            const url = `${API_BASE_URL}/doctor/patients${query ? `?search=${query}` : ""}`;
            const res = await fetch(url, {
                headers: token ? { Authorization: `Bearer ${token}` } : undefined
            });
            const data = await res.json();
            if (data.success) {
                setPatients(data.data);
            }
        } catch (err) {
            console.error(err);
            toast.error("Failed to fetch patients");
        } finally {
            setLoading(false);
        }
    };

    // Initial load/search
    useEffect(() => {
        searchPatients();
    }, [token]);

    const requestAccess = async (patientId: string) => {
        const toastId = toast.loading("Sending request...");
        try {
            const res = await fetch(`${API_BASE_URL}/doctor/patients/${patientId}/request-access`, {
                method: "POST",
                headers: token ? { Authorization: `Bearer ${token}` } : undefined
            });
            const data = await res.json();
            if (data.success) {
                // Refresh list to update status
                searchPatients(search);
                toast.success("Access request sent!", { id: toastId });
            } else {
                toast.error(data.message || "Failed to send request", { id: toastId });
            }
        } catch (err) {
            console.error(err);
            toast.error("Network error", { id: toastId });
        }
    };

    return (
        <div className="space-y-6">
            {/* Search Bar */}
            <div className="relative group">
                <input
                    type="text"
                    placeholder="Search patients by name or email..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && searchPatients(search)}
                    className="w-full pl-12 pr-32 py-4 bg-white dark:bg-slate-900 rounded-2xl border-2 border-transparent focus:border-teal-500/20 shadow-sm focus:ring-0 transition-all dark:text-white"
                />
                <Search className="w-5 h-5 text-slate-400 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-teal-500 transition-colors" />
                <div className="absolute right-2 top-2 bottom-2">
                    <button
                        onClick={() => searchPatients(search)}
                        disabled={loading}
                        className="h-full px-6 bg-slate-900 text-white dark:bg-white dark:text-slate-900 rounded-xl text-sm font-bold hover:opacity-90 disabled:opacity-50 transition-all"
                    >
                        {loading ? "..." : "Search"}
                    </button>
                </div>
            </div>

            {/* Results */}
            <div className="grid grid-cols-1 gap-4">
                {loading && patients.length === 0 ? (
                    <div className="text-center py-10 opacity-50">Searching...</div>
                ) : patients.length === 0 ? (
                    <div className="text-center py-10 opacity-50">No patients found.</div>
                ) : (
                    patients.map(patient => (
                        <div key={patient.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 flex items-center justify-between shadow-sm hover:shadow-md transition-all group">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 rounded-full bg-gradient-to-br from-slate-100 to-slate-200 dark:from-slate-800 dark:to-slate-700 flex items-center justify-center text-slate-500 font-bold text-lg">
                                    {patient.name.charAt(0)}
                                </div>
                                <div>
                                    <h3 className="font-bold text-slate-900 dark:text-white group-hover:text-teal-600 transition-colors">{patient.name}</h3>
                                    <p className="text-xs text-slate-500">{patient.email}</p>
                                </div>
                            </div>

                            <div>
                                {patient.consentStatus === 'APPROVED' ? (
                                    <button
                                        onClick={() => navigate(`/doctor/patients/${patient.id}`)}
                                        className="flex items-center gap-2 px-5 py-2.5 bg-teal-50 text-teal-700 hover:bg-teal-100 rounded-xl text-xs font-bold transition-all"
                                    >
                                        <Unlock className="w-3.5 h-3.5" />
                                        View Records
                                    </button>
                                ) : patient.consentStatus === 'PENDING' ? (
                                    <span className="flex items-center gap-2 px-5 py-2.5 bg-yellow-50 text-yellow-700 rounded-xl text-xs font-bold ring-1 ring-yellow-100">
                                        <Lock className="w-3.5 h-3.5" />
                                        Request Pending
                                    </span>
                                ) : patient.consentStatus === 'REJECTED' ? (
                                    <button
                                        onClick={() => requestAccess(patient.id)}
                                        className="flex items-center gap-2 px-5 py-2.5 bg-red-50 text-red-700 hover:bg-red-100 rounded-xl text-xs font-bold transition-all"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" />
                                        Retry Request
                                    </button>
                                ) : (
                                    <button
                                        onClick={() => requestAccess(patient.id)}
                                        className="flex items-center gap-2 px-5 py-2.5 bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-xl text-xs font-bold transition-all shadow-sm hover:shadow"
                                    >
                                        <UserPlus className="w-3.5 h-3.5" />
                                        Request Access
                                    </button>
                                )}
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

import { type FormEvent, useState } from "react";
import { useHealthTrack } from "../../context/HealthTrackContext";
import toast from "react-hot-toast";
import { type EmergencyProfile } from "../../types/models";

export default function EmergencyCard() {
  const { emergencyProfile, updateEmergencyProfile } = useHealthTrack();

  const [bloodGroup, setBloodGroup] = useState(emergencyProfile?.bloodGroup ?? "");
  const [allergies, setAllergies] = useState(emergencyProfile?.allergies.join(", ") ?? "");
  const [conditions, setConditions] = useState(emergencyProfile?.chronicConditions.join(", ") ?? "");
  const [medications] = useState(emergencyProfile?.medications.join(", ") ?? "");
  const [visibility, setVisibility] = useState(emergencyProfile?.visibility ?? {
    bloodGroup: true,
    allergies: true,
    chronicConditions: true,
    medications: true,
    emergencyContacts: true,
  });

  const [contactName, setContactName] = useState(emergencyProfile?.emergencyContacts[0]?.name ?? "");
  const [contactRelation] = useState(emergencyProfile?.emergencyContacts[0]?.relation ?? "");
  const [contactPhone, setContactPhone] = useState(emergencyProfile?.emergencyContacts[0]?.phone ?? "");

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    const payload: EmergencyProfile = {
      bloodGroup: bloodGroup.trim(),
      allergies: allergies.split(",").map((a) => a.trim()).filter(Boolean),
      chronicConditions: conditions.split(",").map((c) => c.trim()).filter(Boolean),
      medications: medications.split(",").map((m) => m.trim()).filter(Boolean),
      emergencyContacts: contactName
        ? [
          {
            name: contactName.trim(),
            relation: contactRelation.trim() || "Family",
            phone: contactPhone.trim(),
          },
        ]
        : [],
      visibility,
    };

    try {
      await toast.promise(updateEmergencyProfile(payload), {
        loading: "Saving Profile...",
        success: "Emergency Profile Secured",
        error: "Failed to save profile",
      });
    } catch (err) {
      console.error(err);
    }
  };

  const toggleVisibility = (key: keyof typeof visibility) => {
    setVisibility(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const hasRisks =
    (allergies && allergies.trim().length > 0) ||
    (conditions && conditions.trim().length > 0);

  const VisibilityToggle = ({ label, field }: { label: string, field: keyof typeof visibility }) => (
    <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-200/50 dark:border-slate-800/50">
      <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{label} Public Visibility</span>
      <button
        type="button"
        onClick={() => toggleVisibility(field)}
        className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus:outline-none ${visibility[field] ? 'bg-teal-600' : 'bg-slate-300 dark:bg-slate-700'
          }`}
      >
        <span
          className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${visibility[field] ? 'translate-x-5' : 'translate-x-1'
            }`}
        />
      </button>
    </div>
  );

  return (
    <div className="glass-panel p-6 rounded-3xl space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-base font-bold text-slate-800 dark:text-slate-100 italic">
          Emergency Essentials
        </h2>
        {hasRisks && (
          <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-500/10 text-red-600 dark:text-red-400 text-[10px] font-bold uppercase tracking-tight border border-red-500/20">
            <div className="w-1 h-1 rounded-full bg-red-500 animate-pulse"></div>
            High Attention
          </span>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <div className="flex items-center justify-between px-1">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Blood Group</label>
            </div>
            <input
              value={bloodGroup}
              onChange={(e) => setBloodGroup(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200/50 dark:border-slate-700/50 rounded-2xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 transition-all text-slate-800 dark:text-slate-200"
              placeholder="e.g., B+"
              required
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest pl-1">Allergies</label>
            <input
              value={allergies}
              onChange={(e) => setAllergies(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200/50 dark:border-slate-700/50 rounded-2xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 transition-all text-slate-800 dark:text-slate-200"
              placeholder="Penicillin, Peanuts"
            />
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-400 uppercase tracking-widest pl-1">Chronic Conditions</label>
          <textarea
            value={conditions}
            onChange={(e) => setConditions(e.target.value)}
            className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200/50 dark:border-slate-700/50 rounded-2xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 transition-all text-slate-800 dark:text-slate-200 min-h-[80px] resize-none"
            placeholder="Asthma, Diabetes..."
          />
        </div>

        <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800/50">
          <h3 className="text-xs font-bold text-slate-800 dark:text-slate-200 uppercase tracking-widest italic">Emergency Contact</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input
              value={contactName}
              onChange={(e) => setContactName(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200/50 dark:border-slate-700/50 rounded-2xl px-4 py-3 text-sm focus:outline-none text-slate-800 dark:text-slate-200"
              placeholder="Full Name"
            />
            <input
              value={contactPhone}
              onChange={(e) => setContactPhone(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200/50 dark:border-slate-700/50 rounded-2xl px-4 py-3 text-sm focus:outline-none text-slate-800 dark:text-slate-200"
              placeholder="Phone Number"
            />
          </div>
        </div>

        {/* Public Visibility Settings */}
        <div className="pt-4 border-t border-slate-100 dark:border-slate-800/50 space-y-3">
          <h3 className="text-xs font-bold text-slate-800 dark:text-slate-200 uppercase tracking-widest italic mb-2 px-1">
            Privacy Control (Public QR)
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <VisibilityToggle label="Blood" field="bloodGroup" />
            <VisibilityToggle label="Allergies" field="allergies" />
            <VisibilityToggle label="Chronic" field="chronicConditions" />
            <VisibilityToggle label="Meds" field="medications" />
            <VisibilityToggle label="Contacts" field="emergencyContacts" />
          </div>
        </div>

        <button
          type="submit"
          className="w-full mt-2 px-4 py-3.5 rounded-2xl bg-teal-600 text-white text-sm font-bold hover:bg-teal-700 transition-all active:scale-[0.98] shadow-lg shadow-teal-900/20"
        >
          Secure Emergency Data
        </button>
      </form>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface DragDropZoneProps {
    onFileSelect: (file: File) => void;
    selectedFile: File | null;
}

export default function DragDropZone({ onFileSelect, selectedFile }: DragDropZoneProps) {
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const files = e.dataTransfer.files;
        if (files && files.length > 0) {
            onFileSelect(files[0]);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (files && files.length > 0) {
            onFileSelect(files[0]);
        }
    };

    return (
        <div className="relative">
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                className="hidden"
                accept=".pdf,.jpg,.jpeg,.png"
            />

            <motion.div
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
                animate={{
                    scale: isDragging ? 0.98 : 1,
                    borderColor: isDragging ? 'rgba(20, 184, 166, 0.5)' : 'rgba(226, 232, 240, 0.5)',
                    backgroundColor: isDragging ? 'rgba(20, 184, 166, 0.05)' : 'transparent',
                }}
                className={`group relative cursor-pointer overflow-hidden rounded-3xl border-2 border-dashed py-12 px-6 text-center transition-all ${isDragging ? 'shadow-2xl shadow-teal-500/10' : 'hover:border-teal-500/30'
                    }`}
            >
                <div className="flex flex-col items-center gap-4">
                    <motion.div
                        animate={{ y: isDragging ? -5 : 0 }}
                        className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-colors ${isDragging ? 'bg-teal-500 text-white' : 'bg-slate-50 dark:bg-slate-900 text-slate-400 group-hover:text-teal-500'
                            }`}
                    >
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                        </svg>
                    </motion.div>

                    <div className="space-y-1">
                        <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100 uppercase tracking-widest">
                            {selectedFile ? 'Change Document' : 'Drop Health Record'}
                        </h3>
                        <p className="text-[10px] text-slate-500 font-medium">
                            PDF, JPEG, or PNG up to 10MB
                        </p>
                    </div>
                </div>

                <AnimatePresence>
                    {selectedFile && (
                        <motion.div
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: 10 }}
                            className="mt-6 p-4 rounded-2xl bg-teal-500/5 border border-teal-500/10 flex items-center justify-between"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-lg bg-teal-500 flex items-center justify-center text-white">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                </div>
                                <div className="text-left">
                                    <p className="text-xs font-bold text-slate-800 dark:text-slate-200 truncate max-w-[180px]">{selectedFile.name}</p>
                                    <p className="text-[10px] text-slate-400">{(selectedFile.size / 1024 / 1024).toFixed(2)} MB</p>
                                </div>
                            </div>
                            <button
                                onClick={(e) => { e.stopPropagation(); onFileSelect(null as any); }}
                                className="p-1.5 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-slate-400 hover:text-red-500 transition-colors"
                            >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                            </button>
                        </motion.div>
                    )}
                </AnimatePresence>
            </motion.div>
        </div>
    );
}

// src/components/records/RecordList.tsx
import { useState } from "react";
import { Link } from "react-router-dom";
import type { HealthRecord } from "../../types/models";
import { useHealthTrack } from "../../context/HealthTrackContext";
import toast from "react-hot-toast";

interface Props {
  records: HealthRecord[];
}

import { motion } from "framer-motion";

interface Props {
  records: HealthRecord[];
}

export default function RecordList({ records }: Props) {
  const { deleteRecord } = useHealthTrack();
  const [deletingId, setDeletingId] = useState<string | null>(null);

  if (!records.length) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="glass-panel p-12 text-center rounded-2xl"
      >
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 mb-4">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
        </div>
        <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-1">No records found</h3>
        <p className="text-sm text-slate-500 dark:text-slate-400">Try adjusting your search or upload a new document.</p>
      </motion.div>
    );
  }

  const handleDelete = async (id: string, title: string) => {
    // ... same logic ...
    const ok = window.confirm(`Are you sure you want to delete "${title}"? This cannot be undone.`);
    if (!ok) return;

    setDeletingId(id);
    try {
      await deleteRecord(id);
      toast.success("Record deleted");
    } catch (err: any) {
      console.error(err);
      toast.error(err?.message || "Failed to delete record");
    } finally {
      setDeletingId(null);
    }
  };

  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.03 }
    }
  };

  const item = {
    hidden: { opacity: 0, x: -10 },
    show: { opacity: 1, x: 0 }
  };

  return (
    <div className="glass-panel rounded-2xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="min-w-full text-sm">
          <thead className="bg-slate-50/50 dark:bg-slate-800/50 border-b border-slate-200/50 dark:border-slate-700/50 text-slate-500 dark:text-slate-400 font-medium lowercase tracking-wider">
            <tr>
              <th className="px-6 py-4 text-left font-semibold">Title</th>
              <th className="px-6 py-4 text-left font-semibold">Type</th>
              <th className="px-6 py-4 text-left font-semibold">Provider</th>
              <th className="px-6 py-4 text-left font-semibold">Date</th>
              <th className="px-6 py-4 text-left font-semibold">Status</th>
              <th className="px-6 py-4 text-right font-semibold">Actions</th>
            </tr>
          </thead>
          <motion.tbody
            variants={container}
            initial="hidden"
            animate="show"
            className="divide-y divide-slate-100 dark:divide-slate-800/50"
          >
            {records.map((r) => (
              <motion.tr
                key={r.id}
                variants={item}
                className="group hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors"
              >
                <td className="px-6 py-4">
                  <Link
                    to={`/records/${r.id}`}
                    className="font-semibold text-slate-900 dark:text-white hover:text-teal-600 dark:hover:text-teal-400 transition-colors"
                  >
                    {r.title}
                  </Link>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className="px-2.5 py-1 rounded-full bg-slate-100 dark:bg-slate-800 text-[10px] font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 border border-slate-200/50 dark:border-slate-700/50">
                    {r.type.replace("_", " ")}
                  </span>
                </td>
                <td className="px-6 py-4 text-slate-600 dark:text-slate-400 whitespace-nowrap">{r.providerName}</td>
                <td className="px-6 py-4 text-slate-500 dark:text-slate-500 whitespace-nowrap">
                  {new Date(r.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  {r.blockchainVerified ? (
                    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-500/10 dark:bg-emerald-400/10 text-emerald-600 dark:text-emerald-400 text-xs font-medium border border-emerald-500/20">
                      <div className="w-1 h-1 rounded-full bg-emerald-500 animate-pulse"></div>
                      Verified
                    </span>
                  ) : (
                    <span className="px-2.5 py-1 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 text-xs font-medium">
                      Pending
                    </span>
                  )}
                </td>
                <td className="px-6 py-4 text-right whitespace-nowrap">
                  <button
                    onClick={() => handleDelete(r.id, r.title)}
                    disabled={deletingId === r.id}
