interface EmergencyInfo {
    name: string;
    bloodGroup?: string;
    allergies?: string[];
    chronicConditions?: string[];
    medications?: string[];
    emergencyContacts?: { name: string; phone: string; relation: string }[];
    lastUpdated: string;
}

export default function PublicProfilePage() {
